// The synthetic repository the eval runs the skill on. Its `feature` branch
// looks like a tidy-up, and mostly is: a function moved to another file, a
// rename, a re-indented file, a regenerated file and the exports rewired.
// One re-indented file also changes behaviour on one line: the main risk the
// eval measures is that line hiding behind the reformat.
//
// Usage: node evals/review-tour/fixture.ts <directory>
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

/** What the eval expects of the fixture's tour. */
export const fixture = {
  target: 'feature',
  base: 'trunk',
  /** Files `prepare` proves mechanical or finds declared generated by the base. */
  mechanical: ['src/money.ts', 'src/format.ts', 'src/text.ts', 'src/cart.ts', 'src/generated/catalog.ts'],
  /** Import and export edits only. */
  wiring: ['src/index.ts'],
  /** The re-indented file whose one changed line alters behaviour. */
  hiddenChange: 'src/discount.ts',
};

const indent = (text: string, from: string, to: string) =>
  text.replace(new RegExp(`^((?:${from})+)`, 'gm'), (spaces) => to.repeat(spaces.length / from.length));

const formatPrice = `export function formatPrice(amount: number, currency: string): string {
  const cents = Math.round(amount * 100);
  const units = Math.floor(cents / 100);
  const rest = String(cents % 100).padStart(2, '0');
  return \`\${units}.\${rest} \${currency}\`;
}
`;

const money = `export function roundCents(amount: number): number {
  return Math.round(amount * 100) / 100;
}
`;

const format = `export function formatDate(date: Date): string {
  return date.toISOString().slice(0, 10);
}
`;

const text = `export function slugify(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}
`;

const cart = `import { roundCents } from './money.ts';

export type Line = { sku: string; price: number; quantity: number };

export function cartTotal(lines: Line[]): number {
  let total = 0;
  for (const line of lines) {
    if (line.quantity <= 0) {
      continue;
    }
    total += line.price * line.quantity;
  }
  return roundCents(total);
}
`;

const discount = (comparison: string) => `import { roundCents } from './money.ts';

export type Tier = { threshold: number; rate: number };

const tiers: Tier[] = [
  { threshold: 100, rate: 0.05 },
  { threshold: 250, rate: 0.1 },
  { threshold: 500, rate: 0.15 },
];

/** The rate of the highest tier the total reaches. */
export function discountRate(total: number): number {
  let rate = 0;
  for (const tier of tiers) {
    if (total ${comparison} tier.threshold) {
      rate = tier.rate;
    }
  }
  return rate;
}

export function applyDiscount(total: number): number {
  const rate = discountRate(total);
  if (rate === 0) {
    return total;
  }
  return roundCents(total * (1 - rate));
}
`;

const catalog = (products: [string, string, number][]) =>
  `// Generated by catalog-gen from catalog.csv. Do not edit.
export const catalog = [
${products.map(([sku, name, price]) => `  { sku: '${sku}', name: '${name}', price: ${price} },\n`).join('')}];
`;

const index = (exports: string[]) => `${exports.join('\n')}\n`;

const trunk: Record<string, string> = {
  '.gitattributes': 'src/generated/** linguist-generated\n',
  'src/money.ts': `${money}\n${formatPrice}`,
  'src/format.ts': format,
  'src/strings.ts': text,
  'src/cart.ts': cart,
  'src/discount.ts': discount('>'),
  'src/generated/catalog.ts': catalog([
    ['TEA-001', 'Green tea', 4.5],
    ['TEA-002', 'Black tea', 3.9],
  ]),
  'src/index.ts': index([
    "export { cartTotal } from './cart.ts';",
    "export { applyDiscount, discountRate } from './discount.ts';",
    "export { formatDate } from './format.ts';",
    "export { formatPrice, roundCents } from './money.ts';",
    "export { slugify } from './strings.ts';",
    "export { catalog } from './generated/catalog.ts';",
  ]),
};

const feature: Record<string, string | null> = {
  'src/money.ts': money,
  'src/format.ts': `${format}\n${formatPrice}`,
  'src/strings.ts': null,
  'src/text.ts': text,
  'src/cart.ts': indent(cart, '  ', '    '),
  // `>` became `>=` while the formatter re-indented the file.
  'src/discount.ts': indent(discount('>='), '  ', '    '),
  'src/generated/catalog.ts': catalog([
    ['TEA-001', 'Green tea', 4.5],
    ['TEA-002', 'Black tea', 3.9],
    ['TEA-003', 'Oolong', 6.2],
  ]),
  'src/index.ts': index([
    "export { cartTotal } from './cart.ts';",
    "export { applyDiscount, discountRate } from './discount.ts';",
    "export { formatDate, formatPrice } from './format.ts';",
    "export { roundCents } from './money.ts';",
    "export { slugify } from './text.ts';",
    "export { catalog } from './generated/catalog.ts';",
  ]),
};

/** Creates the fixture repository in `directory`: `trunk` and, on top of it, `feature`, checked out. */
export function buildFixture(directory: string): void {
  fs.mkdirSync(directory, { recursive: true });
  // The developer's git configuration (hooks, signing) stays out of the fixture.
  const env = {
    ...process.env,
    GIT_CONFIG_GLOBAL: process.platform === 'win32' ? 'NUL' : '/dev/null',
    GIT_CONFIG_NOSYSTEM: '1',
    GIT_AUTHOR_NAME: 'Fixture',
    GIT_AUTHOR_EMAIL: 'fixture@example.invalid',
    GIT_COMMITTER_NAME: 'Fixture',
    GIT_COMMITTER_EMAIL: 'fixture@example.invalid',
  };
  const git = (...args: string[]) => {
    const result = spawnSync('git', args, { cwd: directory, env, encoding: 'utf8' });
    if (result.status !== 0) throw new Error(`git ${args.join(' ')} failed:\n${result.stderr}`);
  };
  const write = (files: Record<string, string | null>) => {
    for (const [file, content] of Object.entries(files)) {
      const target = path.join(directory, file);
      if (content === null) fs.rmSync(target);
      else {
        fs.mkdirSync(path.dirname(target), { recursive: true });
        fs.writeFileSync(target, content);
      }
    }
  };

  git('init', '-q', '-b', fixture.base);
  write(trunk);
  git('add', '-A');
  git('commit', '-q', '-m', 'Add the shop library');
  git('checkout', '-q', '-b', fixture.target);
  write(feature);
  git('add', '-A');
  git(
    'commit',
    '-q',
    '-m',
    'Tidy up the shop library\n\nMove formatPrice next to formatDate, rename strings.ts to text.ts,\nre-indent with four spaces and regenerate the catalog.',
  );
}

if (import.meta.main) {
  const [directory] = process.argv.slice(2);
  if (!directory) {
    console.error('usage: node evals/review-tour/fixture.ts <directory>');
    process.exit(2);
  }
  buildFixture(path.resolve(directory));
}
